functions.registered_address:
def registered_address(user: User, locale: str | None = None) -> str:
    """Return only the resident's own registered address for delivery copy."""
    current_locale = normalize_locale(locale or getattr(user, "locale", "pt"))
    street = " ".join(part for part in [user.street, user.number] if part).strip()
    parts = [part for part in [street, user.neighborhood, user.municipality] if part]
    return " — ".join(parts) if parts else _missing_locality(current_locale)

functions.safe_notice_cause:
def safe_notice_cause(notice: OutageNotice) -> str | None:
    """Return a source-provided cause only when it is not an address-list fallback."""
    cause = " ".join((notice.description or "").split())
    raw = " ".join((notice.raw_text or "").split())
    if not cause:
        return None
    if cause == raw and _SOURCE_ADDRESS_MARKER.search(cause):
        return None
    return cause[:500]

functions.resident_notification_details:
def resident_notification_details(
    locale: str,
    user: User,
    notice: OutageNotice,
    *,
    include_scheduled_time: bool = False,
) -> str:
    """Render only available, safe facts as a compact WhatsApp detail block."""
    labels = {
        "pt": {
            "address": "📍 Endereço cadastrado",
            "date": "📅 Data",
            "time": "🕒 Horário",
            "cause": "🛠 Motivo informado",
        },
        "en": {
            "address": "📍 Registered address",
            "date": "📅 Date",
            "time": "🕒 Time",
            "cause": "🛠 Reported cause (as published)",
        },
        "es": {
            "address": "📍 Dirección registrada",
            "date": "📅 Fecha",
            "time": "🕒 Hora",
            "cause": "🛠 Motivo informado por la fuente",
        },
    }[locale]
    rows = [f"{labels['address']}: {registered_address(user, locale)}"]
    if include_scheduled_time:
        date, time = _scheduled_date_time(notice)
        if date:
            rows.append(f"{labels['date']}: {date}")
        if time:
            rows.append(f"{labels['time']}: {time}")
    if cause := safe_notice_cause(notice):
        rows.append(f"{labels['cause']}: {cause}")
    return "\n".join(rows)
